import{_ as a,a as t,b as o,c as l,d as i,e as n,f as s,g as h}from"./chunks/autog2_4.DXO1QpAf.js";import{_ as u,c as p,o as d,al as r,j as b}from"./chunks/framework.CT7RwC5a.js";const T=JSON.parse('{"title":"ThunderFly Auto-G2 Autogyro","description":"","frontmatter":{},"headers":[],"relativePath":"uk/frames_autogyro/thunderfly_auto_g2.md","filePath":"uk/frames_autogyro/thunderfly_auto_g2.md"}'),c={name:"uk/frames_autogyro/thunderfly_auto_g2.md"};function m(f,e,g,_,y,k){return d(),p("div",null,e[0]||(e[0]=[r('<h1 id="thunderfly-auto-g2-autogyro" tabindex="-1">ThunderFly Auto-G2 Autogyro <a class="header-anchor" href="#thunderfly-auto-g2-autogyro" aria-label="Permalink to &quot;ThunderFly Auto-G2 Autogyro&quot;">​</a></h1><p>The <em>ThunderFly Auto-G2</em> is an autopilot-controlled autogyro based on the Durafly™ Auto-G2 Gyrocopter RC model, with several parts of the original model substituted for 3D printable ones.</p><p><img src="'+a+'" alt="Auto-G2"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Auto-G2 autogyro’s airframe was originally developed by <a href="https://www.thunderfly.cz/" target="_blank" rel="noreferrer">ThunderFly</a> and has since evolved into the updated <a href="https://docs.thunderfly.cz/instruments/TF-G2" target="_blank" rel="noreferrer">TF-G2 platform</a>. Check out our site for more information on the current <a href="https://www.thunderfly.cz/tf-g2.html" target="_blank" rel="noreferrer">TF-G2 commercial airframe</a>.</p></div><p>All the added parts are available on <a href="https://github.com/ThunderFly-aerospace/Auto-G2" target="_blank" rel="noreferrer">GitHub</a> as an open-source project. Printed parts are designed in <a href="https://www.openscad.org/" target="_blank" rel="noreferrer">OpenSCAD</a>.</p><h2 id="модифікаціі" tabindex="-1">Модифікації <a class="header-anchor" href="#модифікаціі" aria-label="Permalink to &quot;Модифікації&quot;">​</a></h2><p>Durafly Auto-G2, у своєму оригінальному дизайні, має трьохлопастний ротор з лопатями завдовжки 400 мм з профілем CLARK-Y. Головка ротора дозволяє нахил у вісі ROLL лише. Автогиро керується рулем та ліфтом. Durafly Auto-G2 коробка автожира містить полістирольне тіло автожира, регулятор швидкості, двигун (мабуть 800 кВт), 4 сервопривода, хвостові аеродинамічні профілі, 3 лопаті з частинами центру ротора, дротову шасі та попередньовідкручувач.</p><p>Модифікація моделі Durafly виглядає наступним чином:</p><ul><li>Додавання автопілота</li><li>Головка ротора з двома осями вільності (крен, кривошип)</li><li>Two-blade rotor with safely breakable rotor plate</li><li>Більші посадочні шасі</li></ul><h3 id="автопілот" tabindex="-1">Автопілот <a class="header-anchor" href="#автопілот" aria-label="Permalink to &quot;Автопілот&quot;">​</a></h3><p>Літак з усіма модифікаціями вже досить важкий. Therefore a low-weight flight controller is recommended (e.g. <a href="./../flight_controller/holybro_pix32.html">Holybro pix32</a> or <a href="./../flight_controller/cuav_v5_nano.html">CUAV nano</a>).</p><p>The autopilot should be mounted on the bottom side of the autogyro on a 3D-printed damping pad. We have used the damping platform found on <a href="https://www.thingiverse.com/thing:160655" target="_blank" rel="noreferrer">thingiverse</a></p><h3 id="голова-ротора" tabindex="-1">Голова ротора <a class="header-anchor" href="#голова-ротора" aria-label="Permalink to &quot;Голова ротора&quot;">​</a></h3><p>The rotor head is (compared to the original autogyro) modified so that it allows a motion in both roll and pitch axes. Завдяки цьому ротор може контролювати обертання, а також підйом автогира. Directional control of an autogyro by the rotor is possible even in the case of low airspeed compared to the original rudder and elevator control.</p><p>Напечатана головка ротора складається з трьох частин. Нижня частина закручується за допомогою винта М2,5 до оригінального пілона з фанери. Гвинт M3x35, знайдений між першою та другою частиною, створює вільність по осі кроку, а з&#39;єднання між другою та третьою частиною - вільність по осі кочення. Останній вісь складається з гвинта M3x30 з самоблокуючою гайкою. З боку ротора головка шурупа має велику площу шайби.</p><p>Вісь ротора, виготовлена з високої міцності гвинта M3x50, проходить через третю частину. Використовуються підшипники 623 2Z C3 SKF. В кінці цієї частини є кульові вали, прикріплені за допомогою гвинтів M2.5 до сервоприводів, розташованих у нижній частині пілона. It is preferable to exchange these original servos for better quality ones as they are weak and in the original construction, they help each other.</p><p><img src="'+t+'" alt="Rotorhead"></p><h3 id="двоклиновии-ротор" tabindex="-1">Двоклиновий ротор <a class="header-anchor" href="#двоклиновии-ротор" aria-label="Permalink to &quot;Двоклиновий ротор&quot;">​</a></h3><p>The original Durafly Auto-G2 autogyro has a three-blade rotor, which has been modified in this build to use a two-blade rotor. Причини - це зменшення вібрації та спрощення конструкції. Надруковані центральні частини призначені для використання як з китайськими лопатями Durafly, так і з надрукованими на 3D принтері лопатями.</p><p>The rotor&#39;s central part consists of several components, which have the following roles:</p><ul><li>Вони дозволяють лопатці вільно коливатися.</li><li>They have deformation zones that break upon impact with the ground. Завдяки цьому ротор зазвичай можна швидко відремонтувати, замінивши лише один компонент.</li><li>Easy setup of blades&#39; angle-of-attack.</li></ul><h4 id="лопатки-ротора-hobbyking" tabindex="-1">Лопатки ротора HobbyKing <a class="header-anchor" href="#лопатки-ротора-hobbyking" aria-label="Permalink to &quot;Лопатки ротора HobbyKing&quot;">​</a></h4><p>Можна використовувати надруковану центральну частину ротора з оригінальними лопатями. These blades can be bought on <a href="https://hobbyking.com/en_us/duraflytm-auto-g-gyrocopter-821mm-replacement-main-blade-1pcs-bag.html" target="_blank" rel="noreferrer">HobbyKing</a>. Hobbyking blades differ in the position of the center of gravity, and it is therefore necessary to balance them properly.</p><h4 id="роторні-лопаті-надруковані-у-3d" tabindex="-1">Роторні лопаті, надруковані у 3D <a class="header-anchor" href="#роторні-лопаті-надруковані-у-3d" aria-label="Permalink to &quot;Роторні лопаті, надруковані у 3D&quot;">​</a></h4><p>Також можливо надрукувати лопаті ротора.</p><p>The printed rotor blades are still under development, but preliminary tests show they are of better quality, mostly thanks to their precise shape and absence of longitudinal grooves. Проте деякі з процесів виробництва все ще потребують налаштування.</p><p><img src="'+o+'" alt="Blades assembly"></p><h4 id="балансування" tabindex="-1">Балансування <a class="header-anchor" href="#балансування" aria-label="Permalink to &quot;Балансування&quot;">​</a></h4><p>Proper blade balance is very important to minimize vibrations. Леза повинні бути збалансовані таким чином, щоб центр ваги знаходився в середині осі ротора.</p><p>Printed blades are balanced in the production process, and there is no need to further balance them.</p><h3 id="випуск-пристрою" tabindex="-1">Випуск пристрою <a class="header-anchor" href="#випуск-пристрою" aria-label="Permalink to &quot;Випуск пристрою&quot;">​</a></h3><p>If you want to launch an autogyro using a winch or if you want to launch it by towing, you need to print a release device. It is a small box equipped with a servo that pulls out the pin and releases the rope.</p><p>Вся частина склеєна за допомогою гарячого клейового розчину під двигуном на нижній частині корпусу автогиро. Якщо автогир буксирується за допомогою каната, його двигун не повинен бути увімкнений. Це може бути вирішено, наприклад, нулюючи вихід двигуна в передавачі, якщо вимикач пристрою вивільнення закритий.</p><p><img src="'+l+'" alt="Release device"></p><h2 id="список-деталеи" tabindex="-1">Список деталей <a class="header-anchor" href="#список-деталеи" aria-label="Permalink to &quot;Список деталей&quot;">​</a></h2><h3 id="електроніка" tabindex="-1">Електроніка <a class="header-anchor" href="#електроніка" aria-label="Permalink to &quot;Електроніка&quot;">​</a></h3><ul><li>Autopilot (<a href="./../flight_controller/holybro_pix32.html">Holybro pix32</a>, <a href="./../flight_controller/cuav_v5_nano.html">CUAV nano</a>)</li><li>GPS (Модуль GPS NEO-6M, з патч-антеною)</li><li>Airspeed sensor (<a href="https://www.sensirion.com/en/flow-sensors/differential-pressure-sensors/worlds-smallest-differential-pressure-sensor/" target="_blank" rel="noreferrer">SDP3x</a>)</li><li>Stronger servos as a substitution for the original ones (optional), (<a href="https://www.blue-bird-model.com/products_detail/411.htm" target="_blank" rel="noreferrer">BlueBird BMS-125WV</a>)</li><li>Додатковий сервопривід для пристрою відпускання (необов&#39;язково)</li></ul><h3 id="механічні-деталі" tabindex="-1">Механічні деталі <a class="header-anchor" href="#механічні-деталі" aria-label="Permalink to &quot;Механічні деталі&quot;">​</a></h3><ul><li>Підшипник роторної головки (623 2Z C3)</li><li>Propeller (<a href="https://www.apcprop.com/product/10x7e/" target="_blank" rel="noreferrer">APC 10x7</a>)</li><li><a href="https://mpjet.com/shop/gb/prop-adapters/184-collet-prop-adapter-19-mm-4-mm-shaft-m629-standard.html" target="_blank" rel="noreferrer">Prop adapter</a></li></ul><h3 id="друковані-частини" tabindex="-1">Друковані частини <a class="header-anchor" href="#друковані-частини" aria-label="Permalink to &quot;Друковані частини&quot;">​</a></h3><ul><li><p>Голова ротора:</p><ul><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1001.stl" target="_blank" rel="noreferrer">Pylon end</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1002.stl" target="_blank" rel="noreferrer">Pitch part</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1003.stl" target="_blank" rel="noreferrer">Roll part</a></li></ul></li><li><p>Ротор:</p><ul><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1008.stl" target="_blank" rel="noreferrer">center part washer top</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1004.stl" target="_blank" rel="noreferrer">center part washer bottom</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1001.stl" target="_blank" rel="noreferrer">center plate with deformation zones</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1005.stl" target="_blank" rel="noreferrer">washers for setting AoA of blades</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1002.stl" target="_blank" rel="noreferrer">Rotor nut</a></li></ul></li><li><p>Лопаті ротора (необов&#39;язково)</p></li><li><p>Держатель автопілота</p></li><li><p><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1010.stl" target="_blank" rel="noreferrer">Release device</a></p></li><li><p><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1011.stl" target="_blank" rel="noreferrer">Front wheels</a></p></li></ul><h3 id="рекомендовані-запасні-частини" tabindex="-1">Рекомендовані запасні частини <a class="header-anchor" href="#рекомендовані-запасні-частини" aria-label="Permalink to &quot;Рекомендовані запасні частини&quot;">​</a></h3><ul><li>Servos with improved quality (recommended <a href="https://www.blue-bird-model.com/products_detail/411.htm" target="_blank" rel="noreferrer">BlueBird BMS-125WV</a>, original servos are not very durable))</li><li>Propeller (<a href="https://www.apcprop.com/product/10x7e/" target="_blank" rel="noreferrer">APC 10x7</a>)</li><li>Центральна пластина ротора з деформаційними зонами (надрукована в 3D)</li><li>Rotor blades (<a href="https://hobbyking.com/en_us/duraflytm-auto-g-gyrocopter-821mm-replacement-main-blade-1pcs-bag.html" target="_blank" rel="noreferrer">HobbyKing</a> or 3D printed)</li></ul><h2 id="відео" tabindex="-1">Відео <a class="header-anchor" href="#відео" aria-label="Permalink to &quot;Відео&quot;">​</a></h2>',44),b("lite-youtube",{videoid:"YhXXSWz5wWs",title:"[ThunderFly] 3D printed autogyro rotor"},null,-1),r('<h2 id="фотогалерея-змін" tabindex="-1">Фотогалерея змін <a class="header-anchor" href="#фотогалерея-змін" aria-label="Permalink to &quot;Фотогалерея змін&quot;">​</a></h2><p><img src="'+i+'" alt="Auto-G2 1"><img src="'+n+'" alt="Auto-G2 2"><img src="'+s+'" alt="Auto-G2 3"><img src="'+h+'" alt="Auto-G2 4"></p>',2)]))}const v=u(c,[["render",m]]);export{T as __pageData,v as default};
